def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = set(v for row in grid for v in row) - {bg}

    candidates = []
    for color in colors:
        # Prefix sums let us test every possible rectangle efficiently.
        p = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            for c in range(w):
                p[r + 1][c + 1] = (
                    p[r][c + 1] + p[r + 1][c] - p[r][c]
                    + (grid[r][c] == color)
                )

        for r0 in range(h):
            for r1 in range(r0 + 1, h + 1):
                height = r1 - r0
                for c0 in range(w):
                    for c1 in range(c0 + 1, w + 1):
                        width = c1 - c0
                        area = height * width
                        if area < 6:
                            continue
                        count = p[r1][c1] - p[r0][c1] - p[r1][c0] + p[r0][c0]
                        if count >= 5 and count / area >= 0.70:
                            # Favor the full, dense rectangle over smaller
                            # perfect sub-rectangles or broad noisy regions.
                            score = count * count / area
                            candidates.append(
                                (score, color, r0, r1, c0, c1, area)
                            )

    candidates.sort(reverse=True)
    chosen = []
    for score, color, r0, r1, c0, c1, area in candidates:
        overlaps = False
        for _, old_color, a0, a1, b0, b1, old_area in chosen:
            inter = max(0, min(r1, a1) - max(r0, a0)) * max(
                0, min(c1, b1) - max(c0, b0)
            )
            if inter > 0.4 * min(area, old_area):
                overlaps = True
                break
        if not overlaps:
            chosen.append((score, color, r0, r1, c0, c1, area))

    out = [[bg] * w for _ in range(h)]
    for _, color, r0, r1, c0, c1, _ in chosen:
        for r in range(r0, r1):
            for c in range(c0, c1):
                out[r][c] = color
    return out
